<?php
namespace App\Events; use App\Models\Message; use Illuminate\Broadcasting\PrivateChannel; use Illuminate\Contracts\Broadcasting\ShouldBroadcastNow; use Illuminate\Foundation\Events\Dispatchable; use Illuminate\Queue\SerializesModels;
class MessageSent implements ShouldBroadcastNow { use Dispatchable,SerializesModels; public function __construct(public Message $message){} public function broadcastOn(): array{return [new PrivateChannel('conversation.'.$this->message->conversation_id)];} public function broadcastAs():string{return 'message.sent';} public function broadcastWith():array{return ['message'=>MessengerPayload::message($this->message)];} }
class MessengerPayload { public static function message(Message $message):array { $message->loadMissing(['sender:id,name,email,avatar','replyTo.sender:id,name','reactions']); return ['id'=>$message->id,'conversation_id'=>$message->conversation_id,'sender_id'=>$message->sender_id,'message'=>$message->message,'type'=>$message->type,'file_name'=>$message->file_name,'file_size'=>$message->file_size,'file_mime_type'=>$message->file_mime_type,'file_url'=>$message->file_path ? route('messenger.attachments.show',$message) : null,'created_at'=>$message->created_at?->toISOString(),'edited_at'=>$message->edited_at?->toISOString(),'deleted_at'=>$message->deleted_at?->toISOString(),'sender'=>['id'=>$message->sender->id,'name'=>$message->sender->name,'email'=>$message->sender->email,'avatar_url'=>$message->sender->avatar_url],'reply_to'=>$message->replyTo ? ['id'=>$message->replyTo->id,'message'=>$message->replyTo->message,'sender'=>$message->replyTo->sender?->name] : null,'reactions'=>$message->reactions->map(fn($r)=>['emoji'=>$r->emoji,'user_id'=>$r->user_id])->values()]; } }
